mapper.select:
SELECT  FROM interview_preparation_link l
WHERE l.owner_id=#{owner} AND l.event_id=#{eventId}
AND l.status=#{status}
AND l.id > #{afterId}
ORDER BY l.id ASC LIMIT #{limit}

SELECT c.id,c.owner_id,c.kind,c.status,c.revision,c.current_version_id,v.id AS version_id,v.version_number,v.title
FROM question_collection c JOIN question_collection_version v ON v.owner_id=c.owner_id AND v.collection_id=c.id
WHERE c.owner_id=#{owner} AND c.id=#{id} AND v.id=#{versionId}


SELECT ,e.revision AS event_revision,e.status AS event_status,
  e.title AS event_title,e.start_at AS event_start_at,e.zone_id AS event_zone_id
FROM interview_preparation_link l JOIN interview_event e ON e.owner_id=l.owner_id AND e.id=l.event_id
WHERE l.owner_id=#{owner} AND l.status='ACTIVE' AND (l.event_id=#{eventId}

    OR (l.event_id <> #{eventId} AND

        (l.source_kind=#{source.kind} AND l.source_id=#{source.sourceId})
      )
  )
ORDER BY l.id ASC LIMIT 501

mapper.update:
UPDATE interview_preparation_link SET revision=#{row.revision},source_version_id=#{row.sourceVersionId},
  status=#{row.status},updated_at=#{row.updatedAt}
WHERE owner_id=#{row.ownerId} AND event_id=#{row.eventId} AND id=#{row.id} AND revision=#{expected}
  AND source_kind=#{row.sourceKind} AND source_id=#{row.sourceId}

mapper.select:
SELECT revision,change_kind,event_revision,snapshot_json,source_stamp_json,created_at
FROM interview_preparation_link_history WHERE owner_id=#{owner} AND event_id=#{eventId} AND link_id=#{id}
AND revision < #{before}
ORDER BY revision DESC LIMIT #{limit}
